.payplanetsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1b2433;
    background: linear-gradient(160deg, #f3f5f9 0%, #e8edf4 100%);
    border-radius: 18px;
}

.payplanetsim-container * {
    box-sizing: border-box;
}

.payplanetsim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #10243f 0%, #16365c 55%, #1f4e79 100%);
    color: #f4f8fd;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(16, 36, 63, 0.32);
    border-bottom: 4px solid #c9a23a;
}

.payplanetsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.payplanetsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #e9cf8a;
    background: rgba(201, 162, 58, 0.18);
    padding: 5px 14px;
    border-radius: 999px;
}

.payplanetsim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #d7e2ee;
}

.payplanetsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #1f4e79;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.payplanetsim-period-counter #currentDay,
.payplanetsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #10243f;
}

.payplanetsim-round-name {
    background: #dde6f1;
    color: #10243f;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.payplanetsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a6b12;
    background: #fbf1d7;
    padding: 4px 12px;
    border-radius: 999px;
}

.payplanetsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.payplanetsim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #d9e1ec;
    box-shadow: 0 4px 14px rgba(16, 36, 63, 0.06);
    border-top: 4px solid #1f4e79;
}

.payplanetsim-card-approval { border-top-color: #1f4e79; }
.payplanetsim-card-credibility { border-top-color: #2f8f6b; }
.payplanetsim-card-retention { border-top-color: #b06a1c; }
.payplanetsim-card-material { border-top-color: #c9a23a; }

.payplanetsim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6a7689;
}

.payplanetsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #10243f;
}

.payplanetsim-card-approval .payplanetsim-value { color: #1f4e79; }
.payplanetsim-card-credibility .payplanetsim-value { color: #2f8f6b; }
.payplanetsim-card-retention .payplanetsim-value { color: #b06a1c; }
.payplanetsim-card-material .payplanetsim-value { color: #a9851f; }

.payplanetsim-sublabel {
    font-size: 0.76rem;
    color: #76839a;
    line-height: 1.35;
}

.payplanetsim-approval-fail .payplanetsim-value { color: #c0392b; }
.payplanetsim-approval-pass .payplanetsim-value { color: #2f8f6b; }

.payplanetsim-retention-low { border-top-color: #c0392b; }
.payplanetsim-retention-low .payplanetsim-value { color: #c0392b; }

.payplanetsim-material-band .payplanetsim-value { color: #2f8f6b; }

.payplanetsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #10243f;
    color: #eaf1f9;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.payplanetsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #e9cf8a;
}

.payplanetsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #c9a23a;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(16, 36, 63, 0.05);
}

.payplanetsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.payplanetsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #10243f;
    margin-bottom: 6px;
}

.payplanetsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #344256;
}

.payplanetsim-briefing-text strong { color: #2f8f6b; }
.payplanetsim-briefing-text em { color: #9a6b12; font-style: italic; }

.payplanetsim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #d9e1ec;
    box-shadow: 0 4px 14px rgba(16, 36, 63, 0.06);
}

.payplanetsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #10243f;
    border-bottom: 2px solid #e8edf4;
    padding-bottom: 8px;
}

.payplanetsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #21324a;
    margin: 14px 0 6px;
}

.payplanetsim-container select,
.payplanetsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c2cfe0;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #f7f9fc;
    color: #1b2433;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.payplanetsim-container select:focus,
.payplanetsim-container input[type="number"]:focus {
    outline: none;
    border-color: #1f4e79;
    box-shadow: 0 0 0 3px rgba(31, 78, 121, 0.15);
}

.payplanetsim-container select option {
    background-color: #ffffff;
    color: #1b2433;
}

.payplanetsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #c9a23a;
}

.payplanetsim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #1f4e79;
    margin-top: 4px;
}

.payplanetsim-range-readout span:nth-child(2) {
    color: #2f8f6b;
    font-weight: 800;
}

.payplanetsim-hint {
    font-size: 0.8rem;
    color: #76839a;
    margin-top: 4px;
    line-height: 1.4;
}

.payplanetsim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 6px;
}

.payplanetsim-check-row {
    display: flex;
    align-items: flex-start;
    gap: 10px;
    background: #f4f7fb;
    border: 1px solid #dde6f1;
    border-radius: 9px;
    padding: 10px 12px;
}

.payplanetsim-check-row input[type="checkbox"] {
    width: 18px;
    height: 18px;
    margin-top: 2px;
    flex: 0 0 18px;
    accent-color: #2f8f6b;
}

.payplanetsim-check-label {
    flex: 1;
    margin: 0 !important;
    font-size: 0.88rem;
    font-weight: 600 !important;
    color: #21324a;
    cursor: pointer;
}

.payplanetsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.payplanetsim-container .btn-primary {
    background: linear-gradient(135deg, #1f4e79 0%, #2f8f6b 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(31, 78, 121, 0.28);
}

.payplanetsim-container .btn-primary:hover {
    filter: brightness(1.07);
}

.payplanetsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #c2cfe0;
    color: #6a7689;
}

.payplanetsim-coach {
    background: #10243f;
    color: #eaf1f9;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(16, 36, 63, 0.24);
    border-left: 5px solid #c9a23a;
}

.payplanetsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #e9cf8a;
    margin-bottom: 8px;
}

.payplanetsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.payplanetsim-coach-body strong { color: #e9cf8a; }
.payplanetsim-coach-body em { color: #f0b97f; font-style: italic; }

.payplanetsim-history,
.payplanetsim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #d9e1ec;
    box-shadow: 0 4px 14px rgba(16, 36, 63, 0.06);
}

.payplanetsim-history h3,
.payplanetsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #10243f;
}

.payplanetsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #21324a;
}

.payplanetsim-container table#usfHistoryTable th {
    background: #eef2f8;
    color: #10243f;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d6e0ec;
}

.payplanetsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef2f7;
}

.payplanetsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f8fafc;
}

.payplanetsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .payplanetsim-container {
        padding: 14px;
    }
    .payplanetsim-header h1 {
        font-size: 1.7rem;
    }
    .payplanetsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .payplanetsim-value {
        font-size: 2rem;
    }
    .payplanetsim-clock {
        margin-left: 0;
    }
    .payplanetsim-period-counter {
        font-size: 0.88rem;
    }
    .payplanetsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .payplanetsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* ===== v1.1.0 completion message — append-only ===== */
.payplanet-cm{background:#ffffff;border:1px solid #dfe3ea;border-radius:12px;padding:22px 24px;margin:18px 0;color:#1b2433;font-family:inherit;box-shadow:0 2px 10px rgba(16,24,44,0.06);}
.payplanet-cm-head{text-align:center;border-bottom:1px solid #eef0f4;padding-bottom:14px;margin-bottom:14px;}
.payplanet-cm-title{font-size:15px;font-weight:600;letter-spacing:.02em;color:#1c7a43;text-transform:uppercase;}
.payplanet-cm-scorewrap{margin:8px 0 2px;}
.payplanet-cm-score{font-size:52px;font-weight:800;color:#1c7a43;line-height:1;}
