.payplanet-cm-grade{font-size:18px;font-weight:700;color:#1b2433;margin-top:4px;}
.payplanet-cm-badges{margin-top:10px;display:flex;gap:8px;justify-content:center;flex-wrap:wrap;}
.payplanet-cm-badge{display:inline-block;padding:4px 12px;border-radius:999px;font-size:12px;font-weight:700;letter-spacing:.02em;}
