.payplanet-cm-insights{background:#f9fafc;border:1px solid #eceff4;border-radius:9px;padding:12px 16px;}
.payplanet-cm-insights-title{font-size:13px;font-weight:700;color:#1c7a43;margin-bottom:6px;text-transform:uppercase;letter-spacing:.02em;}
.payplanet-cm-insights ul{margin:0;padding-left:18px;}
.payplanet-cm-insights li{font-size:13.5px;line-height:1.5;color:#2b3242;margin-bottom:6px;}

