(function() {
    'use strict';

    class PayPlanetAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Paying for the Planet`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card.
            this.VARIABLE_PAY = 2940000;     // ~EUR 2.94M variable pay under redesign
            this.START_APPROVAL = 68;        // last AGM say-on-pay support
            this.TARGET_APPROVAL = 80;       // sub-80% = governance crisis
            this.START_CREDIBILITY = 30;     // token 5% modifier = weak credibility
            this.START_RETENTION = 70;       // CEO motivated under current design
            this.START_ESG_WEIGHT = 5;       // current token ESG weighting (%)
            this.MATERIAL_FLOOR = 441000;    // ~15% of 2.94M — lower edge of material band
            this.MATERIAL_CEIL = 882000;     // ~30% of 2.94M — upper edge of material band
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                const startEsg = Math.round(this.VARIABLE_PAY * this.START_ESG_WEIGHT / 100);
                state.domainState = {
                    approval: this.START_APPROVAL,
                    credibility: this.START_CREDIBILITY,
                    retention: this.START_RETENTION,
                    esgWeight: this.START_ESG_WEIGHT,
                    esgPay: startEsg,
                    ltiShare: 0,
                    capPct: 0,
                    gate: false,
                    clawback: false,
                    greenwashFlag: false,
                    voteWon: false,
                    approvalHistory: [this.START_APPROVAL],
                    credibilityHistory: [this.START_CREDIBILITY],
                    retentionHistory: [this.START_RETENTION],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults = deliberately middling/neutral, NOT the textbook-correct play.
                state.decisions = {
                    root: `disclosure`,
                    credible: `bumpmodifier`,
                    honesty: 50,
                    weight: 10,
                    lti: 50,
                    structure: `modifier`,
                    metricPrimary: `intensity`,
                    metricSecond: `engagement`,
                    cap: 200,
                    gate: true,
                    clawback: true,
                    ceo: `capitulate`,
                    investor: `maxweight`,
                    disclose: `minimal`,
                    conviction: 60
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const root = document.getElementById(`rootInput`);
                const cred = document.getElementById(`credibleInput`);
                const hon = document.getElementById(`honestyInput`);
                if (root) decisions.root = root.value;
                if (cred) decisions.credible = cred.value;
                if (hon) decisions.honesty = parseInt(hon.value, 10);
                if (!Number.isFinite(decisions.honesty) || decisions.honesty < 0 || decisions.honesty > 100) {
                    warn(`warn_honesty_range`); return false;
                }
            } else if (round === 2) {
                const w = document.getElementById(`weightInput`);
                const lti = document.getElementById(`ltiInput`);
                const st = document.getElementById(`structureInput`);
                if (w) decisions.weight = parseInt(w.value, 10);
                if (lti) decisions.lti = parseInt(lti.value, 10);
                if (st) decisions.structure = st.value;
                if (![10, 20, 30, 40].includes(decisions.weight)) {
                    warn(`warn_weight_choice`); return false;
                }
                if (!Number.isFinite(decisions.lti) || decisions.lti < 0 || decisions.lti > 100) {
                    warn(`warn_lti_range`); return false;
                }
            } else if (round === 3) {
                const mp = document.getElementById(`metricPrimaryInput`);
                const ms = document.getElementById(`metricSecondInput`);
                const cap = document.getElementById(`capInput`);
                const gate = document.getElementById(`gateInput`);
                const cb = document.getElementById(`clawbackInput`);
                if (mp) decisions.metricPrimary = mp.value;
                if (ms) decisions.metricSecond = ms.value;
                if (cap) decisions.cap = parseInt(cap.value, 10);
                if (gate) decisions.gate = !!gate.checked;
                if (cb) decisions.clawback = !!cb.checked;
                if (!Number.isFinite(decisions.cap) || decisions.cap < 0) {
                    warn(`warn_cap_invalid`); return false;
                }
            } else if (round === 4) {
                const ceo = document.getElementById(`ceoInput`);
                const inv = document.getElementById(`investorInput`);
                const dis = document.getElementById(`discloseInput`);
                const cv = document.getElementById(`convictionInput`);
                if (ceo) decisions.ceo = ceo.value;
                if (inv) decisions.investor = inv.value;
                if (dis) decisions.disclose = dis.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // approval = projected say-on-pay support; credibility = verifiable/gaming-resistant;
            // retention = CEO motivation & winnability; greenwash = unverifiable-ESG penalty driver.
            let approvalDelta = 0, credibilityDelta = 0, retentionDelta = 0;
            let greenwash = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose: token ESG + weak pay-for-performance alignment (Common Error 1).
                switch (d.root) {
                    case `tokenmisalign`: credibilityDelta += 9; approvalDelta += 2; coachKey = `coach_r1_root_right`; break;
                    case `disclosure`: credibilityDelta += 1; approvalDelta -= 3; coachKey = `coach_r1_disclosure`; break;
                    case `toomuchpay`: credibilityDelta -= 4; retentionDelta -= 6; coachKey = `coach_r1_toomuchpay`; break;
                    case `investors`: credibilityDelta -= 7; approvalDelta -= 6; coachKey = `coach_r1_investors`; break;
                }

                // What "credible" means: material weight on verifiable climate metrics in the LTI.
                switch (d.credible) {
                    case `verifiable`: credibilityDelta += 8; approvalDelta += 3;
                        if (d.root === `tokenmisalign`) coachKey = `coach_r1_diag_sharp`; break;
                    case `bumpmodifier`: credibilityDelta -= 4; approvalDelta -= 4; coachKey = `coach_r1_bump`; break;
                    case `softculture`: credibilityDelta -= 7; greenwash += 4; coachKey = `coach_r1_soft`; break;
                    case `nochange`: credibilityDelta -= 9; approvalDelta -= 6; coachKey = `coach_r1_nochange`; break;
                }

                // Candour: willingness to confront the alignment gap rather than protect the CEO.
                if (d.honesty >= 60) { credibilityDelta += 4; }
                else if (d.honesty <= 25) { credibilityDelta -= 6; coachKey = `coach_r1_lowhonesty`; }

                summaryKey = (d.root === `tokenmisalign` && d.credible === `verifiable`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Set the financial-vs-ESG weighting & STI/LTI split (Common Errors 1 & 2).
                ds.esgWeight = d.weight;
                ds.ltiShare = d.lti;
                ds.esgPay = Math.round(this.VARIABLE_PAY * d.weight / 100);
                const material = ds.esgPay >= this.MATERIAL_FLOOR && ds.esgPay <= this.MATERIAL_CEIL;

                // 30% is the materiality sweet spot; 20% emerging norm; 10% token; 40% destabilizing.
                switch (d.weight) {
                    case 10: approvalDelta -= 7; credibilityDelta -= 3; retentionDelta += 4; coachKey = `coach_r2_token`; break;
                    case 20: approvalDelta += 6; credibilityDelta += 3; retentionDelta += 1; coachKey = `coach_r2_norm`; break;
                    case 30: approvalDelta += 8; credibilityDelta += 5; retentionDelta -= 3; coachKey = `coach_r2_material`; break;
                    case 40: approvalDelta += 2; credibilityDelta += 1; retentionDelta -= 13; coachKey = `coach_r2_overweight`; break;
                }
                if (material) { approvalDelta += 3; }

                // Climate is long-term: ESG belongs in the LTI, not the annual bonus (Error: STI loading).
                if (d.lti >= 60) { credibilityDelta += 6; retentionDelta += 3;
                    if (d.weight === 30) coachKey = `coach_r2_ltiright`; }
                else if (d.lti <= 30) { credibilityDelta -= 6; coachKey = `coach_r2_stiload`; }

                // Standalone weighted component is more visible/auditable than a modifier.
                if (d.structure === `standalone`) { credibilityDelta += 4; approvalDelta += 2; }
                else { credibilityDelta -= 4; approvalDelta -= 2; greenwash += 2; }

                summaryKey = (d.weight === 30 && d.lti >= 60 && d.structure === `standalone`) ? `sum_r2_good`
                    : (d.weight === 10 ? `sum_r2_token` : (d.weight === 40 ? `sum_r2_overweight` : `sum_r2_weak`));
            } else if (round === 3) {
                // Choose indicators & cap incentive intensity (Common Errors 3 & 4).
                // Absolute Scope 1+2 is the metric the 2030 thesis rests on; intensity can fall while
                // absolute rises; self-assessed culture/engagement are unauditable under CSRD.
                let verifiable = 0;
                switch (d.metricPrimary) {
                    case `absolute`: credibilityDelta += 11; approvalDelta += 4; verifiable++; coachKey = `coach_r3_absolute`; break;
                    case `intensity`: credibilityDelta -= 9; approvalDelta -= 6; greenwash += 6; coachKey = `coach_r3_intensity`; break;
                    case `culture`: credibilityDelta -= 13; approvalDelta -= 4; greenwash += 8; coachKey = `coach_r3_culture`; break;
                }
                switch (d.metricSecond) {
                    case `revenue`: credibilityDelta += 5; approvalDelta += 3; verifiable++; break;
                    case `sbti`: credibilityDelta += 7; approvalDelta += 4; verifiable++; break;
                    case `engagement`: credibilityDelta -= 9; approvalDelta -= 4; greenwash += 6; coachKey = `coach_r3_engagement`; break;
                }
                if (verifiable === 2 && d.metricPrimary === `absolute`) {
                    credibilityDelta += 3; coachKey = `coach_r3_verifset`;
                }

                // Cap limits windfalls; no cap = damaging optics (Common Error 4).
                switch (d.cap) {
                    case 150: approvalDelta += 5; credibilityDelta += 3; retentionDelta -= 4; break;
                    case 175: approvalDelta += 5; credibilityDelta += 4; retentionDelta -= 1; coachKey = (verifiable >= 2 ? `coach_r3_capgate` : coachKey); break;
                    case 200: approvalDelta += 1; retentionDelta += 3; break;
                    case 0: approvalDelta -= 13; credibilityDelta -= 9; retentionDelta += 5; coachKey = `coach_r3_nocap`; break;
                }

                // Financial gate: ESG should not pay out amid poor financial results.
                if (d.gate) { approvalDelta += 4; credibilityDelta += 4; }
                else { approvalDelta -= 11; credibilityDelta -= 9; coachKey = `coach_r3_nogate`; }

                // Malus & clawback manage reversal/restatement/misconduct risk.
                if (d.clawback) { approvalDelta += 3; credibilityDelta += 3; }
                else { approvalDelta -= 5; credibilityDelta -= 5; }

                summaryKey = (d.metricPrimary === `absolute` && d.cap !== 0 && d.gate) ? `sum_r3_good`
                    : (d.cap === 0 || !d.gate ? `sum_r3_nogate` : (greenwash >= 6 ? `sum_r3_soft` : `sum_r3_weak`));
            } else if (round === 4) {
                // Defend the policy & recover the vote (two-sided constraint, Common Error 5).
                // Respond to the CEO retention risk without gutting credibility.
                switch (d.ceo) {
                    case `rebalance`: retentionDelta += 11; approvalDelta += 2; credibilityDelta += 2; coachKey = `coach_r4_rebalance`; break;
                    case `capitulate`: retentionDelta += 8; approvalDelta -= 11; credibilityDelta -= 9; greenwash += 4; coachKey = `coach_r4_capitulate`; break;
                    case `ignore`: retentionDelta -= 18; approvalDelta += 1; coachKey = `coach_r4_ignore`; break;
                }

                // What to hold firm on against the investor pushback.
                switch (d.investor) {
                    case `verifiability`: approvalDelta += 6; credibilityDelta += 6; coachKey = (d.ceo === `rebalance` ? `coach_r4_verifiability` : coachKey); break;
                    case `maxweight`: approvalDelta += 1; retentionDelta -= 11; greenwash += 3; coachKey = `coach_r4_maxweight`; break;
                    case `dropgate`: approvalDelta -= 9; credibilityDelta -= 11; greenwash += 5; coachKey = `coach_r4_dropgate`; break;
                }

                // Pre-socializing with CSRD-aligned disclosure recovers the vote.
                switch (d.disclose) {
                    case `transparent`: approvalDelta += 5; credibilityDelta += 4; break;
                    case `minimal`: approvalDelta -= 4; coachKey = `coach_r4_minimal`; break;
                    case `spin`: approvalDelta -= 6; credibilityDelta -= 6; greenwash += 4; coachKey = `coach_r4_spin`; break;
                }

                // Conviction nudges approval.
                approvalDelta += Math.round((d.conviction - 60) / 12);

                summaryKey = (d.ceo === `rebalance` && d.investor === `verifiability` && d.disclose === `transparent`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Greenwashing penalty: unverifiable/soft ESG erodes credibility and investor approval,
            // even if raw weight looks bold. This is what keeps Common Error 2 measurably losing.
            if (greenwash > 0) {
                credibilityDelta -= greenwash * 1.2;
                approvalDelta -= greenwash * 0.8;
                if (greenwash >= 6) ds.greenwashFlag = true;
            }

            // Apply deltas, clamped 0-100 (headroom preserved by modest per-round deltas).
            ds.credibility = Math.max(0, Math.min(100, ds.credibility + credibilityDelta));
            ds.retention = Math.max(0, Math.min(100, ds.retention + retentionDelta));

            // Approval is partly direct and partly pulled by credibility & retention being healthy —
            // a credible package the CEO will stay for is what actually recovers the say-on-pay vote.
            // Gains apply with diminishing returns toward the 100 ceiling so a strong R1–R3 cannot peg
            // approval at 100 before Round 4 — keeping "Defend the Vote" a live lever (a great defence
            // still climbs, while capitulating/spinning visibly drops the vote back below the threshold).
            // Penalties stay linear so the classic errors bite hard. This preserves the 68%→≥80% arc.
            const alignmentApproval = (ds.credibility - 50) * 0.04 + (ds.retention - 50) * 0.02;
            const approvalSwing = approvalDelta + alignmentApproval;
            const appliedApproval = approvalSwing > 0
                ? approvalSwing * ((100 - ds.approval) / 55)
                : approvalSwing;
            ds.approval = Math.max(0, Math.min(100, ds.approval + appliedApproval));

            if (round === 2) {
                ds.esgWeight = d.weight;
                ds.esgPay = Math.round(this.VARIABLE_PAY * d.weight / 100);
            }
            if (round === 3) {
                ds.capPct = d.cap;
                ds.gate = !!d.gate;
                ds.clawback = !!d.clawback;
            }

            ds.approvalHistory.push(Math.round(ds.approval));
            ds.credibilityHistory.push(Math.round(ds.credibility));
            ds.retentionHistory.push(Math.round(ds.retention));

            // v1.1.0 fix: persist instructor-card composite every period (grading reads domainState.performance.overallScore).
            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = this._composite(ds);

            if (round === this.ROUNDS.length) {
                ds.voteWon = ds.approval >= this.TARGET_APPROVAL && ds.retention >= 45 && !ds.greenwashFlag;
            }

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                approval: Math.round(ds.approval),
                approvalDelta: Math.round(appliedApproval),
                credibility: Math.round(ds.credibility),
                credibilityDelta: Math.round(credibilityDelta),
                retention: Math.round(ds.retention),
                retentionDelta: Math.round(retentionDelta),
                esgWeight: ds.esgWeight,
                esgPay: ds.esgPay,
                greenwashFlag: ds.greenwashFlag,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtMoney(value) {
            const lang = (window.mySimulation && window.mySimulation.language) || `en`;
            const v = Number(value) || 0;
            if (lang === `es`) {
                if (v >= 1000000) {
                    const m = (v / 1000000).toFixed(1).replace(`.`, `,`);
                    return m + ` M€`;
                }
                return Math.round(v / 1000) + ` mil €`;
            }
            if (v >= 1000000) {
                return `€` + (v / 1000000).toFixed(1) + `M`;
            }
            return `€` + Math.round(v / 1000) + `K`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);
            uiManager.bind(`approvalDisplay`, `domainState.approval`, (v) => {
                const card = document.querySelector(`.payplanetsim-card-approval`);
                if (card) {
                    card.classList.toggle(`payplanetsim-approval-pass`, Number(v) >= this.TARGET_APPROVAL);
                    card.classList.toggle(`payplanetsim-approval-fail`, Number(v) < this.TARGET_APPROVAL);
                }
                return Math.round(Number(v)) + `%`;
            });
            uiManager.bind(`credibilityDisplay`, `domainState.credibility`, (v) => Math.round(v));
            uiManager.bind(`retentionDisplay`, `domainState.retention`, (v) => {
                const card = document.querySelector(`.payplanetsim-card-retention`);
                if (card) card.classList.toggle(`payplanetsim-retention-low`, Number(v) < 45);
                return Math.round(v);
            });
            uiManager.bind(`materialDisplay`, `domainState.esgPay`, (v) => {
                const card = document.querySelector(`.payplanetsim-card-material`);
                const inBand = Number(v) >= this.MATERIAL_FLOOR && Number(v) <= this.MATERIAL_CEIL;
                if (card) card.classList.toggle(`payplanetsim-material-band`, inBand);
                return this._fmtMoney(v);
            });
            uiManager.bind(`budgetDisplay`, `domainState.esgPay`, (v) => {
                const lang = (window.mySimulation && window.mySimulation.language) || `en`;
                const esg = this._fmtMoney(v);
                const total = this._fmtMoney(this.VARIABLE_PAY);
                if (lang === `es`) return `ESG ` + esg + ` / ` + total + ` total`;
                return `ESG ` + esg + ` / ` + total + ` total`;
            });

            const self = this;

            // Honesty slider readout.
            const hon = document.getElementById(`honestyInput`);
            const honReadout = document.getElementById(`honestyReadout`);
            if (hon && honReadout) {
                honReadout.textContent = hon.value;
                hon.addEventListener(`input`, function() { honReadout.textContent = hon.value; });
            }

            // LTI-share slider readout.
            const lti = document.getElementById(`ltiInput`);
            const ltiReadout = document.getElementById(`ltiReadout`);
            if (lti && ltiReadout) {
                ltiReadout.textContent = lti.value;
                lti.addEventListener(`input`, function() { ltiReadout.textContent = lti.value; });
            }

            // Weighting -> live ESG-at-stake preview in the readout near the selector.
            const w = document.getElementById(`weightInput`);
            if (w) {
                const showEsg = function() {
                    const pct = parseInt(w.value, 10) || 0;
                    const esg = Math.round(self.VARIABLE_PAY * pct / 100);
                    const counter = document.querySelector(`.payplanetsim-clock`);
                    // non-essential live hint; leaves the headline counter intact otherwise
                    if (counter && self._weightHintActive) counter.textContent = self._fmtMoney(esg);
                };
                w.addEventListener(`change`, showEsg);
            }
        }

