        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.approvalHistory.map((_, i) => (i === 0 ? this._cl(`chart_start`) : this._cl(`chart_round_prefix`) + i));
            return {
                payplanetChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.approvalHistory },
                        { data: ds.credibilityHistory },
                        { data: ds.retentionHistory }
                    ]
                }
            };
        }

        _composite(ds) {
            const approval = Math.round(ds.approval);
            const credibility = Math.round(ds.credibility);
            const retention = Math.round(ds.retention);
            return Math.round(Math.min(100, approval) * 0.40 + credibility * 0.35 + retention * 0.25);
        }

        _cl(key) {
            return (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(key) : key;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const approval = Math.round(ds.approval);
            const credibility = Math.round(ds.credibility);
            const retention = Math.round(ds.retention);

            const wonVote = approval >= this.TARGET_APPROVAL;
            const credible = credibility >= 60 && !ds.greenwashFlag;
            const retained = retention >= 45;
            const greenwash = ds.greenwashFlag || (credibility < 40 && approval >= this.TARGET_APPROVAL);
            const composite = this._composite(ds);

            let performanceKey = `grade_failed`;
            if (wonVote && credible && retained && composite >= 72) performanceKey = `grade_durable`;
            else if (wonVote && credible && retained) performanceKey = `grade_recovered`;
            else if (wonVote && greenwash) performanceKey = `grade_greenwash`;
            else if (wonVote && !retained) performanceKey = `grade_lostceo`;
            else if (approval > this.START_APPROVAL + 4) performanceKey = `grade_short`;
            const performance = window.mySimulation.t(performanceKey);
            const met = wonVote && credible && retained;

            const insights = [];
            if (wonVote && credible && retained) insights.push(window.mySimulation.t(`insight_durable`));
            else if (wonVote && greenwash) insights.push(window.mySimulation.t(`insight_greenwash`));
            else if (wonVote && !retained) insights.push(window.mySimulation.t(`insight_lostceo`));
            else if (!wonVote) insights.push(window.mySimulation.t(`insight_short`));

            if (ds.greenwashFlag) insights.push(window.mySimulation.t(`insight_unverifiable`));
            if (retention < 45) insights.push(window.mySimulation.t(`insight_retention`));
            if (ds.esgWeight <= 10) insights.push(window.mySimulation.t(`insight_token`));
            if (wonVote && credible && retained && composite >= 80) insights.push(window.mySimulation.t(`insight_exemplary`));

            return {
                approval: approval,
                credibility: credibility,
                retention: retention,
                wonVote: wonVote,
                retained: retained,
                greenwash: greenwash,
                composite: composite,
                performance: performance,
                performanceKey: performanceKey,
                met: met,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k, v) => window.mySimulation.t(k, v);
            const s = summary || {};
            const score = (s.composite != null) ? s.composite : 0;
            const grade = s.performance || (s.performanceKey ? t(s.performanceKey) : ``);
            const badges = [];
            badges.push(`<span class="payplanet-cm-badge ` + (s.met ? `payplanet-cm-met` : `payplanet-cm-fail`) + `">` + (s.met ? t(`cm_met`) : t(`cm_not_met`)) + `</span>`);
            if (!s.wonVote) badges.push(`<span class="payplanet-cm-badge payplanet-cm-fail">` + t(`cm_fail_vote`) + `</span>`);
            if (s.greenwash) badges.push(`<span class="payplanet-cm-badge payplanet-cm-fail">` + t(`cm_fail_greenwash`) + `</span>`);
            if (s.wonVote && !s.retained) badges.push(`<span class="payplanet-cm-badge payplanet-cm-fail">` + t(`cm_fail_ceo`) + `</span>`);
            const kpi = (label, val) => `<div class="payplanet-cm-metric"><div class="payplanet-cm-metric-val">` + val + `</div><div class="payplanet-cm-metric-lbl">` + label + `</div></div>`;
            const kpis = kpi(t(`cm_approval`), (s.approval != null ? s.approval : 0) + `%`) + kpi(t(`cm_credibility`), (s.credibility != null ? s.credibility : 0)) + kpi(t(`cm_retention`), (s.retention != null ? s.retention : 0));
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `<div class="payplanet-cm">`
                + `<div class="payplanet-cm-head"><div class="payplanet-cm-title">` + t(`cm_title`) + `</div>`
                + `<div class="payplanet-cm-scorewrap"><span class="payplanet-cm-score">` + score + `</span><span class="payplanet-cm-score-max">/100</span></div>`
                + `<div class="payplanet-cm-grade">` + grade + `</div>`
                + `<div class="payplanet-cm-badges">` + badges.join(``) + `</div></div>`
                + `<div class="payplanet-cm-metrics">` + kpis + `</div>`
                + `<div class="payplanet-cm-insights"><div class="payplanet-cm-insights-title">` + t(`cm_insights_title`) + `</div><ul>` + insights + `</ul></div>`
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.greenwashFlag) return window.mySimulation.t(`hint_greenwash`);
            if (ds.retention < 40 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_retention`);
            if (ds.credibility < 40) return window.mySimulation.t(`hint_credibility`);
            if (state.currentPeriod >= 3 && ds.approval < 74) return window.mySimulation.t(`hint_behind`);
            if (ds.approval >= this.TARGET_APPROVAL && ds.credibility >= 60 && ds.retention >= 45) return window.mySimulation.t(`hint_strong`);
            return null;
        }

