                { key: `results.approval`, label: `Approval`, i18nKey: `col_approval`, formatter: (v) => Math.round(v) + `%` },
                { key: `results.credibility`, label: `Credibility`, i18nKey: `col_credibility`, formatter: (v) => Math.round(v) },
